/**
 * rehype plugin: turn every `<img src="/images/…">` in rendered markdown
 * into a responsive <img> that references the WebP variants generated by
 * scripts/optimize-images.mjs.
 *
 * Works by reading public/optimized/manifest.json at plugin construction
 * time (same file `src/lib/image.ts` consumes) — no per-render lookups.
 * Images that aren't in the manifest (external URLs, sources under the
 * optimizer's min-width threshold, or images added since last build)
 * pass through untouched.
 */

import { visit } from "unist-util-visit";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const MANIFEST  = path.resolve(__dirname, "../../public/optimized/manifest.json");

function loadManifest() {
  try { return JSON.parse(fs.readFileSync(MANIFEST, "utf8")); }
  catch { return {}; }
}

function pickVariant(variants, suffix) {
  return variants.find((v) => v.endsWith(`-${suffix}.webp`));
}

export default function rehypeResponsiveImages() {
  const manifest = loadManifest();
  return (tree) => {
    visit(tree, "element", (node) => {
      if (node.tagName !== "img") return;
      const props = node.properties;
      const src   = props?.src;
      if (typeof src !== "string" || !src.startsWith("/")) return;
      const entry = manifest[src];
      if (!entry) return;
      const v480  = pickVariant(entry.variants, "480");
      const v800  = pickVariant(entry.variants, "800");
      const v1200 = pickVariant(entry.variants, "1200");
      const full  = pickVariant(entry.variants, "full");
      if (!v800) return;

      // Preserve any classes/alt/attrs the author put in; only add the ones
      // relevant to responsive behavior.
      props.src    = v800;
      props.srcset = [v480 && `${v480} 480w`, `${v800} 800w`, v1200 && `${v1200} 1200w`]
        .filter(Boolean).join(", ");
      // Body prose is a single reading column capped at ~62ch (~900px). Use
      // a matching sizes hint so mobile still picks 480w and desktop picks
      // 800w-1200w depending on layout.
      if (!props.sizes) props.sizes = "(min-width: 1024px) 900px, 100vw";
      if (entry.width  && !props.width)  props.width  = entry.width;
      if (entry.height && !props.height) props.height = entry.height;
      if (full) props["data-hires"] = full;
      if (!props.loading)  props.loading  = "lazy";
      if (!props.decoding) props.decoding = "async";
    });
  };
}
